<script setup>
import { computed, ref, shallowRef } from 'vue'
import { parseGeoJson } from './csvGeoJsonMerger.js'
import { geoJsonToCsv } from './geoJsonToCsv.js'
import { downloadFile } from '../shared/download.js'

const collection = shallowRef(null)
const loading = ref(false)
const exporting = ref(false)
const fileError = ref('')
const exportError = ref('')
const result = ref(null)
const busy = computed(() => loading.value || exporting.value)

async function loadGeoJson(file) {
  collection.value = null
  result.value = null
  fileError.value = ''
  exportError.value = ''
  const selectedFile = Array.isArray(file) ? file[0] : file
  if (!selectedFile) return
  loading.value = true
  try {
    collection.value = parseGeoJson(await selectedFile.text())
  } catch (error) {
    fileError.value = `Could not read GeoJSON: ${error.message}`
  } finally {
    loading.value = false
  }
}

async function exportCsv() {
  if (!collection.value || busy.value) return
  result.value = null
  exportError.value = ''
  exporting.value = true
  await new Promise((resolve) => setTimeout(resolve, 0))
  try {
    downloadFile(geoJsonToCsv(collection.value), 'data.csv', 'text/csv;charset=utf-8')
    result.value = collection.value.features.length
  } catch (error) {
    exportError.value = `Could not export CSV: ${error.message}`
  } finally {
    exporting.value = false
  }
}
const fileUpload = ref()
</script>

<template>
  <!-- Bố cục: VaCard chứa form chọn GeoJSON và xuất CSV; thông tin số feature cùng lỗi/kết quả được đặt gần thao tác liên quan. -->
  <section>
    <h1 class="page-title">GeoJSON → CSV</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportCsv">
          <VaFileUpload
            id="geojson-csv-file"
            v-model="fileUpload"
            type="single"
            upload-button-text="GeoJSON file"
            file-types=".geojson,.json,application/geo+json,application/json"
            :disabled="busy"
            @update:modelValue="loadGeoJson"
          />
          <VaProgressBar v-if="loading" indeterminate aria-label="Reading file" />
          <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
          <VaAlert v-if="fileError" color="danger" role="alert">{{ fileError }}</VaAlert>
          <p v-if="collection" class="text-sm text-secondary" data-testid="geojson-csv-summary">
            {{ collection.features.length }} GeoJSON features
          </p>
          <VaButton type="submit" color="primary" :loading="exporting" :disabled="!collection || busy">
            Export CSV
          </VaButton>
        </VaForm>
        <VaAlert v-if="exportError" color="danger" class="mt-4" role="alert">
          {{ exportError }}
        </VaAlert>
        <VaAlert v-if="result !== null" color="success" class="mt-4" role="status" data-testid="geojson-csv-result">
          {{ result }} rows exported. Downloaded: data.csv.
        </VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
